lt = model.load_state_dict(state_dict, strict=False)\n    assert not result.missing_keys, f\"Missing keys: {result.missing_keys}\"\n    model = model.to(device).eval()\n    return model\n\n\ndef load_val_data(val_file, num_negatives):\n    samples = []\n    with open(val_file) as f:\n        for line in f:\n            if not line.strip():\n                continue\n            d = json.loads(line)\n            neg_candidates = d.get(\"neg_candidates\", [])\n            candidate_tokens = d.get(\"candidate_tokens\", {})\n            neg_texts = []\n            for cid in neg_candidates:\n                t = candidate_tokens.get(cid, \"\")\n                if t:\n                    neg_texts.append(t)\n                if len(neg_texts) >= num_negatives:\n                    break\n            pool_texts = [d[\"pos_tokens\"]] + neg_texts\n            samples.append({\n                \"query_id\": d[\"query_id\"],\n                \"query_text\": d[\"query_tokens\"],\n                \"pool_texts\": pool_texts,\n            })\n    return samples\n\n\ndef batch_encode(model, tokenizer, texts, device, max_len, batch_size):\n    all_embs = []\n    for i in range(0, len(texts), batch_size):\n        batch = texts[i:i+batch_size]\n        enc = tokenizer(batch, truncation=True, max_length=max_len,\n                       padding=True, return_tensors=\"pt\")\n        enc = {k: v.to(device) for k, v in enc.items()}\n        with torch.no_grad():\n            emb = model.encode(enc[\"input_ids\"], enc[\"attention_mask\"])\n        all_embs.append(emb.cpu())\n    return torch.cat(all_embs, dim=0)\n\n\ndef compute_per_instance_r1(model, tokenizer, samples, device, max_len, batch_size):\n    all_query_texts = [s[\"query_text\"] for s in samples]\n    all_pool_texts = []\n    pool_offsets = []\n    offset = 0\n    for s in samples:\n        pool = s[\"pool_texts\"]\n        all_pool_texts.extend(pool)\n        pool_offsets.append((offset, offset + len(pool)))\n        offset +=