er = sum(1 for d in deltas if d > 0)\n    n_worse = sum(1 for d in deltas if d < 0)\n    n_tied = sum(1 for d in deltas if d == 0)\n\n    print(f\"\\n{'='*60}\", flush=True)\n    print(\"Paired Analysis\", flush=True)\n    print(f\"Instances: {len(deltas)}, Repos: {len(unique_repos)}\", flush=True)\n    print(f\"Embedding better: {n_better}, worse: {n_worse}, tied: {n_tied}\", flush=True)\n    print(f\"R@1 random:    {np.mean(r1_random):.4f}\", flush=True)\n    print(f\"R@1 embedding: {np.mean(r1_embed):.4f}\", flush=True)\n    print(f\"Mean delta:    {np.mean(deltas):.4f}\", flush=True)\n\n    print(f\"\\nCluster bootstrap ({N_BOOTSTRAP} iterations)...\", flush=True)\n    boot = cluster_bootstrap(deltas, repo_ids, N_BOOTSTRAP)\n\n    crosses_zero = boot[\"ci_95\"][0] <= 0 <= boot[\"ci_95\"][1]\n\n    output = {\n        \"method\": f\"cluster bootstrap (repo-level), {N_BOOTSTRAP} iterations\",\n        \"eval_set\": VAL_FILE,\n        \"n_instances\": len(deltas),\n        \"n_repos\": len(unique_repos),\n        \"R@1_random\": float(np.mean(r1_random)),\n        \"R@1_embedding\": float(np.mean(r1_embed)),\n        \"instance_counts\": {\"embedding_better\": n_better, \"embedding_worse\": n_worse, \"tied\": n_tied},\n        \"mean_delta_R@1\": boot[\"mean_delta\"],\n        \"ci_95\": boot[\"ci_95\"],\n        \"p_value\": boot[\"p_value_one_sided\"],\n        \"p_value_two_sided\": boot[\"p_value_two_sided\"],\n        \"bootstrap_std\": boot[\"bootstrap_std\"],\n        \"crosses_zero\": crosses_zero,\n        \"conclusion\": \"NOT statistically significant (CI crosses zero)\" if crosses_zero else \"Statistically significant (CI does not cross zero)\",\n        \"elapsed_seconds\": round(time.time() - t_start, 1),\n    }\n\n    print(f\"\\n{'='*60}\", flush=True)\n    print(\"RESULT\", flush=True)\n    print(json.dumps(output, indent=2), flush=True)\n\n    os.makedirs(os.path.dirname(OUTPUT_PATH), exist_ok=True)\n    with open(OUTPUT_PATH, \"w\") as f:\n      